AMS.MEL.IR.C2.Common.signature:
--  Legacy limited controlled communications-test observer, distinct from
   --  the canonical common request type despite sharing the native engine.
   --  Finalization closes without raising. Observer closure is not cancellation
   --  or direct release of a permit still held by pending native work.
   function Submit_Comms_Test
     (Channel    : Control_Channel;
      Channel_ID : IR.Channel.Comms_Channel_ID;
      Command_ID : C2.Command_ID;
      Request_ID : IR.Channel.Comms_Request_ID) return Comms_Request;

--  Read the rejection category under the declared Rejected precondition;
   --  there is no independent body check.
   --  @param Result Rejected legacy communications-test result.
   --  @return C2 error category mapped from the upstream rejection, not bridge admission failure.
   function Description (Result : Comms_Result) return String
   with Pre => Status (Result) = Rejected;

--  Idempotently clear the public observer without cancelling its future.
   --  Pending native accounting and provider retention survive independently;
   --  unexpected native failure raises a provider error.
   --  @param Request Legacy observer to close, externally serialized against Wait.
   function Capabilities (Channel : Control_Channel) return IR.Channel.Channel_Capability;

AMS.MEL.IR.C2.Metadata.signature:
--  Owned reported command identity/state/reason/text, independent of future
   --  results. Accepted status does not prove physical command execution ended.
   function Command_ID (Value : Command_Status) return C2.Command_ID;

--  Owned active-test report with UCI identity, estimated time and completion
   --  fraction. Provider estimates are preserved, not calculated by the bridge.
   function BIT_ID (Value : Active_BIT) return UCI_ID;

--  Owned completed-test report with UCI identity, end timestamp, outcome,
   --  failure text and ordered item results.
   function BIT_ID (Value : Completed_BIT) return UCI_ID;

--  Owned fault-associated key/value/format/units text. The bridge preserves
   --  descriptions without parsing values or inferring physical units.
   function Key (Value : Fault_Data) return String;

--  Owned ordered diagnostic-test and component UCI references for a fault
   --  ambiguity group; the bridge performs no diagnosis or group resolution.
   function Diagnostic_Test_Count (Value : Fault_Ambiguity_Group) return Natural;

--  Owned fault report with severity/state, detection time, text, associated
   --  data, components and ambiguity groups, preserving provider vector order.
   function Fault_ID (Value : Fault) return UCI_ID;

--  Wholly Ada-owned event snapshot. Kind selects the valid accessor family;
   --  this private representation is not a public discriminated record. Native
   --  event storage is disposed even if Ada copying raises; no borrowed provider
   --  references survive in returned values.
   function Receive
     (Stream : Metadata_Stream; Timeout_Milliseconds : Natural := 0) return Metadata_Event;

--  Count supported tests under the declared configuration-event precondition;
   --  the body does not independently check kind.
   --  @param Event BIT-configuration event to inspect.
   --  @return Number of supported-test definitions in provider order.
   function BIT_Type_At (Event : Metadata_Event; Index : Positive) return BIT_Type
   with Pre => Kind (Event) = BIT_Configuration_Event;

AMS.MEL.IR.C2.signature:
--  Compatibility subtype of the canonical common 32-bit command identifier;
   --  this is the same Ada type and needs no conversion between the two names.
   type BIT_ID is mod 2**32 with Size => 32;

--  Numeric unsigned 32-bit BIT selector used by the upstream BIT command,
   --  not the structured UCI identity used by other interfaces.
   type BIT_ID_Array is array (Positive range <>) of BIT_ID;

--  Unsigned 32-bit scan scalar/identifier. Scan-type controls retain the
   --  upstream integer representation; they are not constrained Ada Booleans.
   type Scan_Parameters is record
      Elevation_Defined_With_Range_And_Altitude : Boolean := False;
      Center_Azimuth_Rad                        : Long_Float := 0.0;
      Center_Elevation_Rad                      : Long_Float := 0.0;
      Center_Frame_Reference_EL                 : Coordinate_Frame_Reference := Inertial;
      Center_Frame_Reference_AZ                 : Coordinate_Frame_Reference := Aircraft;
      Scan_Width_Rad                            : Long_Float := 0.0;
      Scan_Height_Rad                           : Long_Float := 0.0;
      Continuous_Scan                           : Scan_Value := 0;
      Returning                                 : Scan_Value := 0;
      Agile_Scan                                : Scan_Value := 0;
      Scan_ID                                   : Scan_Value := 0;
      Scan_Rate_Rad_Per_Second                  : Long_Float := 0.0;
      Preferred_Revisit_Interval_Seconds        : Long_Float := 0.0;
      Required_Revisit_Interval_Seconds         : Long_Float := 0.0;
      Max_Range_Of_Interest_M                   : Scan_Value := 0;
      Min_Range_Of_Interest_M                   : Scan_Value := 0;
      Elevation_Scan_Center_Altitude_M          : Scan_Value := 0;
      Elevation_Scan_Center_Range_M             : Scan_Value := 0;
      Degradation                               : Degradation_Method := Capacity_Degradation;
   end record;

--  Upstream mode categories, without bridge validation of state/mode pairs.
   --  @enum Unused Mode used for states without internal modes, value 0.
   --  @enum Task_Sched Operational task-scheduling mode, value 1; upstream specifies general MFA support.
   --  @enum Scan_Volume_Sched Operational volume-scan scheduling mode, value 2.
   --  @enum Scan_Bar_Sched Operational bar-scan scheduling growth mode, value 3; not proof of provider support.
   function Submit_Mode
     (Channel         : Control_Channel;
      ID              : Command_ID;
      State           : MFA_State;
      Mode            : MFA_Mode;
      Scan_Parameters : AMS.MEL.IR.C2.Scan_Parameters := Default_Scan_Parameters)
      return Mode_Request;

--  Signed 64-bit system-time count in nanoseconds. Neither the pinned
   --  ConfigSetCommand nor conversion establishes an epoch or clock domain.
   function Submit_Config_Set
     (Channel        : Control_Channel;
      ID             : Command_ID := 0;
      System_Time_NS : System_Time_Nanoseconds := 0;
      Config         : String := "") return Return_Request;

--  Owned cached Mode future result containing a mode or explicit rejection.
   --  This is not a command-status metadata event or a physical transition report.
   function Status (Result : Mode_Result) return Outcome;

--  Owned terminal Return payload or rejection; payload Fail still has a
   --  successful result category. Command-status callbacks remain independent.
   function Status (Result : Return_Result) return Outcome;

--  Idempotently release the public Mode observer. Pending native work retains
   --  its provider graph and admission permit until completion/safe retention;
   --  this call does not cancel it. Native failure raises a provider error.
   --  @param Request Observer to clear, externally serialized against Wait.
   procedure Close (Request : in out Return_Request);

AMS.MEL.IR.Channel.signature:
--  Unsigned 32-bit channel selector carried by a communications-test request;
   --  it is not the UCI identifier used in a channel capability.
   type Comms_Request_ID is mod 2**32 with Size => 32;

--  Unsigned 32-bit communications-test correlation identifier, preserved in
   --  the corresponding report without assigning a bridge-generated sequence.
   type Comms_Test_Report is record
      Command_ID : AMS.MEL.IR.Channel.Command_ID;
      Request_ID : Comms_Request_ID;
   end record;

--  Navigation reference-frame categories, not a coordinate transformation.
   --  @enum LLA Latitude/longitude/altitude representation, upstream value 0.
   --  @enum ECEF Earth-centered, Earth-fixed frame, value 1.
   --  @enum NED_Platform North/east/down frame associated with the platform, value 2.
   --  @enum NED_Sensor North/east/down frame associated with the sensor, value 3.
   type Band_Info is record
      Kind                               : Band_Type;
      Min_Wavelength_M, Max_Wavelength_M : Long_Float;
   end record;

--  Standard positive-index vector of band descriptions, preserving the
   --  provider's per-map-entry vector order and duplicates.
   type Image_Band is record
      Band_Index : Interfaces.Unsigned_32;
      Bands      : Band_Info_Vectors.Vector;
   end record;

--  Standard positive-index vector of navigation frames. Provider order
   --  corresponds to navigation states in frame headers; an empty list is valid.

   type Channel_Capability is private;

--  Value-owned capability snapshot with copied identifiers, location and
   --  collections. Reports do not enable services, allocate image buffers or
   --  establish support for unimplemented Ada APIs. Provider set/map iteration
   --  becomes vector order; the local constructor preserves supplied vectors.
   function Create_Capability
     (Channel_ID                                                                    : UCI_ID;
      Height, Width, Bit_Depth, Row_Pitch, Buffer_Size, Image_Size, Number_Of_Bands :
        Interfaces.Unsigned_32;
      Format                                                                        : Pixel_Format;
      Sensor_Types                                                                  :
        Sensor_Type_Vectors.Vector;
      Platform_ID                                                                   : UCI_ID;
      Sensor_Location                                                               :
        Component_Location;
      Channel_Types                                                                 :
        Channel_Type_Vectors.Vector;
      Task_Schedule_Depth                                                           :
        Interfaces.Unsigned_32;
      ODC_Available, NUC_Available                                                  : Boolean;
      Metadata                                                                      :
        Metadata_Vectors.Vector;
      Image_Bands                                                                   :
        Image_Band_Vectors.Vector;
      Nav_Frames                                                                    :
        Coordinate_Vectors.Vector) return Channel_Capability;

--  Owned terminal outcome and either a Return payload or rejection details.
   --  A successful outcome may contain Fail; it does not certify physical work.
   function Status (Result : Return_Result) return Outcome;

--  Limited controlled observer of one admitted communications-test future.
   --  Independent native retention protects pending work after view, typed owner,
   --  Session or observer Close. It is distinct from the legacy C2 child owner.
   --  Finalization is non-raising; Close must not race Wait on this observer.
   function Submit_Comms_Test
     (Channel    : View;
      Channel_ID : Comms_Channel_ID;
      Command_ID : AMS.MEL.IR.Channel.Command_ID;
      Request_ID : Comms_Request_ID) return Comms_Request;

--  Owned communications-test report or explicit rejection. This future result
   --  is separate from independently registered communications-test metadata.
   function Status (Result : Comms_Result) return Outcome;

--  Read the rejection category. The declared precondition requires Rejected;
   --  assertion-disabled execution has no independent body check.
   --  @param Result Rejected communications-test result.
   --  @return Explicit upstream error code, distinct from bridge admission failure.
   function Description (Result : Comms_Result) return String
   with Pre => Status (Result) = Rejected;

AMS.MEL.IR.Health_Status.Metadata.signature:
--  Owned dependent-subsystem identity, criticality and failure category copied from
   --  SubsystemDepInfo. No severity scale is inferred from criticality.
   function Subsystem_ID (Value : Subsystem_Dependency) return Interfaces.Unsigned_32;

--  Reported failure category without bridge reclassification.
   --  @param Value Owned dependency to inspect.
   --  @return Reported failure category without bridge reclassification.
   type Version is record
      Source, Major_Revision, Minor_Revision, Engineering_Revision : Interfaces.Unsigned_32;
   end record;

--  Owned subsystem computer-software configuration-item data, including independent name text,
   --  version, criticality, failure, BIT change counter and connection indication.
   function CSCI_Name (Value : Subsystem_CSCI) return String;

AMS.MEL.IR.Image.Metadata.signature:
--  Supported defect reason subset; the pinned enum currently defines only Unknown.
   --  @enum Unknown Provider does not identify a specific reason for this bad pixel.
   type Bad_Pixel is record
      Row    : Interfaces.Unsigned_32;
      Column : Interfaces.Unsigned_32;
      Reason : Bad_Pixel_Reason;
   end record;

--  Owned bad-pixel collection with separate source-reported size/count. Actual copied vector
   --  length is authoritative for indexed access; reported counts are not used to truncate the
   --  vector.
   type Azimuth_Elevation is record
      Azimuth_Rad, Elevation_Rad : Long_Float;
   end record;

--  Azimuth/elevation representation based on pinned AMS Math AzEl. Angle components are
   --  radians; the containing rate field must be distinguished from angles.
   --  @field Azimuth_Rad Azimuth component; radians for an angle. The pointing-rate field has no
   --  explicitly documented time denominator upstream.
   --  @field Elevation_Rad Elevation component; radians for an angle. The pointing-rate field has
   --  no explicitly documented time denominator upstream.
   type Line_Of_Sight_Report is record
      System_Time_NS         : Long_Long_Integer;
      Pointing_Angle         : Azimuth_Elevation;
      Pointing_Angle_Rates   : Azimuth_Elevation;
      At_Speed               : Boolean;
      In_Tolerance           : Boolean;
      Platform_Attitude      : AMS.MEL.Status.Euler;
      Validity_Flag_Bitfield : Interfaces.Unsigned_32;
      Image_Rotation_Rad     : Long_Float;
   end record;

--  Source-compatible subtype of the canonical Image Navigation Response, preserving response
   --  timestamp and both identifiers; see that type for units and identity semantics.
   function Reported_Size (Value : Bad_Pixel_List) return Interfaces.Unsigned_32;

--  Copied bad-pixel entry at the one-based sequence index.
   --  @param Value Owned bad-pixel list to inspect.
   --  @param Index One-based position; raises Constraint Error beyond the actual copied length.
   --  @return Copied bad-pixel entry at the one-based sequence index.
   type Metadata_Counters is record
      Events_Received           : AMS.MEL.IR.Counter;
      Events_Dropped_Queue_Full : AMS.MEL.IR.Counter;
      Malformed_Or_Unsupported  : AMS.MEL.IR.Counter;
   end record;

AMS.MEL.IR.Image.signature:
--  Raw sensor and platform navigation uncertainty values. The pinned interface defines neither
   --  units nor bit meanings; the bridge preserves both unsigned values.
   --  @field Sensor_Uncertainties Sensor-reported uncertainty value, not decoded by this bridge.
   --  @field Platform_Uncertainties Platform-reported uncertainty value, not decoded by this
   --  bridge.
   type Contributing_Sensor is record
      Location  : AMS.MEL.IR.Component_Location;
      Sensor_ID : Interfaces.Unsigned_32;
   end record;

--  Selects the stored upstream orientation alternative independently for each orientation or
   --  derivative.
   --  @enum Euler_Orientation Euler representation is active.
   --  @enum Quaternion_Orientation Quaternion representation is active.
   type Orientation (Kind : Orientation_Kind := Euler_Orientation) is record
      case Kind is
         when Euler_Orientation =>
            Euler_Value : AMS.MEL.Status.Euler;

         when Quaternion_Orientation =>
            Quaternion_Value : Quaternion;
      end case;
   end record;

--  Discriminated copy of one upstream orientation alternative. No conversion between Euler and
   --  quaternion representations is performed.
   --  @field Kind Selects the active record component; defaults to the Euler alternative.
   --  @field Euler_Value Euler value when the Euler alternative is selected; see the canonical
   --  Status Euler type.
   --  @field Quaternion_Value X, Y, Z, W value when the quaternion alternative is selected; no
   --  normalization is applied.
   type Sensor_Inertial_State is record
      System_Time_NS                   : Long_Long_Integer;
      Q_XYZW, Q_ECEF_XYZW              : Quaternion;
      Sensor_Position, Sensor_Velocity : Directional;
      Uncertainty                      : Image.Uncertainty;
   end record;

--  Provider identifier for the reference frame of a sensor navigation state. This identifies
   --  the stored data; it does not request a bridge coordinate transformation.
   --  @enum LLA Latitude/longitude/altitude coordinate-system identifier; per-component units are
   --  not specified by SensorNavState.
   --  @enum ECEF Earth-centered Earth-fixed reference frame.
   --  @enum NED_Platform Platform North/East/Down reference-frame identifier.
   --  @enum NED_Sensor Sensor North/East/Down reference-frame identifier.
   type Sensor_Nav_State is record
      Position, Velocity, Acceleration                   : Directional;
      Position_Error, Velocity_Error, Acceleration_Error : Nav_Error;
      Orientation                                        : Image.Orientation;
      Orientation_Error                                  : Nav_Error;
      Orientation_Velocity                               : Image.Orientation;
      Orientation_Velocity_Error                         : Nav_Error;
      Orientation_Acceleration                           : Image.Orientation;
      Orientation_Acceleration_Error                     : Nav_Error;
      Coordinate_System                                  : Image.Coordinate_System;
   end record;

type North_East_Down is record
      North, East, Down : Long_Float;
   end record;

--  North/East/Down components whose units belong to the containing navigation-report field.
   --  @field North North component in the containing field units.
   --  @field East East component in the containing field units.
   --  @field Down Down component in the containing field units.

   type Attitude_Rate is record
      Value          : AMS.MEL.Status.Euler;
      System_Time_NS : Long_Long_Integer;
   end record;

--  Euler attitude-rate values and their associated provider timestamp. The pinned header
   --  supplies an Euler representation but does not explicitly define rate units or a timestamp
   --  epoch.
   --  @field Value Euler components representing attitude rate, passed unchanged to the provider.
   --  @field System_Time_NS Associated attitude-rate time in nanoseconds; clock and epoch are
   --  unspecified.

   type Position_Velocity_Covariance is record
      Position_Position_Pn_Pn : Long_Float;
      Position_Position_Pn_Pe : Long_Float;
      Position_Position_Pn_Pd : Long_Float;
      Position_Position_Pe_Pe : Long_Float;
      Position_Position_Pe_Pd : Long_Float;
      Position_Position_Pd_Pd : Long_Float;
      Position_Velocity_Pn_Vn : Long_Float;
      Position_Velocity_Pn_Ve : Long_Float;
      Position_Velocity_Pn_Vd : Long_Float;
      Position_Velocity_Pe_Ve : Long_Float;
      Position_Velocity_Pe_Vd : Long_Float;
      Position_Velocity_Pd_Vd : Long_Float;
      Velocity_Velocity_Vn_Vn : Long_Float;
      Velocity_Velocity_Vn_Ve : Long_Float;
      Velocity_Velocity_Vn_Vd : Long_Float;
      Velocity_Velocity_Ve_Ve : Long_Float;
      Velocity_Velocity_Ve_Vd : Long_Float;
      Velocity_Velocity_Vd_Vd : Long_Float;
   end record;

AMS.MEL.IR.Instrumentation.signature:
--  Owned attachment configuration for the conditionally required instrumentation channel;
   --  constructing it performs no provider work.
   function Create_Config
     (Channel_ID : UCI_ID; Platform_ID : UCI_ID; Sensor_Location : Component_Location)
      return Instrumentation_Config;

type Instrumentation_Level_Command is record
      Command_ID : Interfaces.Unsigned_32;
      Priority   : Instrumentation.Priority;
   end record;

--  Supplied command controlling how much instrumentation data the MFA records. Sending it does
   --  not itself prove acceptance or completion.
   --  @field Command_ID Caller-supplied command identifier, preserving all 32 bits.
   --  @field Priority Requested Normal or Debug instrumentation recording level.

   type Instrumentation_Report is record
      Command_ID   : Interfaces.Unsigned_32;
      Size         : Interfaces.Unsigned_32;
      Timestamp_NS : Long_Long_Integer;
      Priority     : Instrumentation.Priority;
   end record;

--  Accesses the rejection detail of a terminal result. Requires Status equal to Rejected;
   --  enabled precondition checking raises Assertion Error on violation. The accessor body does
   --  not add an outcome check.
   --  @param Result Owned terminal result satisfying the declared outcome precondition.
   --  @return Independent Ada string containing the complete rejection description.

   type Instrumentation_Request is limited private;

AMS.MEL.IR.Track.Metadata.signature:
--  Limited controlled owner of queue consumption, not the Track/Session or
   --  provider graph. Callback state survives public closure as required;
   --  provider-channel destruction remains the quiescence boundary.
   function Open (Channel : Track_Channel; Queue_Capacity : Positive := 16) return Metadata_Channel;

--  Test local handle presence, not channel existence or callback/queue health.
   --  @param Stream Metadata consumer to inspect.
   --  @return True when its public native handle is present, even if stopped/failed.

   --  Complete RequestSystemTrackData. Every value is copied verbatim from the
   --  published upstream getters; upstream defines no enum and no constrained
   --  field, so every value the provider supplies is well formed.
   type Request_System_Track_Data is record
      System_Time_NS : Long_Long_Integer;
      Command_ID     : Interfaces.Unsigned_32;
      Request_ID     : Interfaces.Unsigned_32;
      Track_ID       : Interfaces.Unsigned_32;
   end record;

--  Copied quaternion components in upstream XYZW order, without normalization
   --  or an inferred rotation convention beyond the containing field's meaning.
   --  @field X Quaternion x component.
   --  @field Y Quaternion y component.
   --  @field Z Quaternion z component.
   --  @field W Quaternion w component, retained separately from xyz.
   type Uncertainty is record
      Sensor_Uncertainties   : Interfaces.Unsigned_32;
      Platform_Uncertainties : Interfaces.Unsigned_32;
   end record;

--  Opaque upstream navigation-uncertainty values, copied without decoding
   --  bit meanings or assigning statistical confidence units.
   --  @field Sensor_Uncertainties Unsigned sensor uncertainty representation, all bits preserved.
   --  @field Platform_Uncertainties Unsigned platform uncertainty representation, all bits preserved.

   --  Complete SensorInertialState. No quaternion is normalized and no vector
   --  is renormalized: upstream performs no such validation.
   type Sensor_Inertial_State is record
      System_Time_NS  : Long_Long_Integer;
      Q_XYZW          : Quaternion;
      Q_ECEF_XYZW     : Quaternion;
      Sensor_Position : Directional;
      Sensor_Velocity : Directional;
      Uncertainties   : Uncertainty;
   end record;

--  Complete HotRegion. Every published getter is represented exactly once
   --  and the geometry keeps its upstream 16-bit width.
   type Hot_Region is record
      Kind   : Hot_Region_Type;
      Size   : Interfaces.Unsigned_16;
      Top    : Interfaces.Unsigned_16;
      Left   : Interfaces.Unsigned_16;
      Right  : Interfaces.Unsigned_16;
      Bottom : Interfaces.Unsigned_16;
   end record;

--  Copied geometry for an extended high-intensity object. Upstream defines
   --  boundary positions as zero-based but does not establish inclusive/exclusive
   --  edge arithmetic here; no geometry consistency check is performed.
   --  @field Kind Provider hot-region category.
   --  @field Size Number of pixels making up the region, unsigned 16-bit.
   --  @field Top Top pixel position, zero-based unsigned 16-bit.
   --  @field Left Left pixel position, zero-based unsigned 16-bit.
   --  @field Right Right pixel position, zero-based unsigned 16-bit.
   --  @field Bottom Bottom pixel position, zero-based unsigned 16-bit.

   --  Complete CandidateObjectHeader. CFAR is upstream binary32 and is kept as
   --  Float; it is deliberately not widened. The validity bitfield is carried
   --  verbatim and is deliberately not decoded.
   type Candidate_Object_Header is record
      Number_Of_COs          : Interfaces.Unsigned_16;
      Stack_Frame_Index      : Interfaces.Unsigned_16;
      CFAR                   : Float;
      Validity_Flag_Bitfield : Interfaces.Unsigned_16;
      TOV_UTC_NS             : Long_Long_Integer;
   end record;

--  Owned fixed header fields; variable hot regions are accessed through the
   --  message. Count meaning differs between fixed-array and PreProc messages.
   --  @field Number_Of_COs Declared unsigned 16-bit candidate count; fixed-array messages use this prefix, PreProc vectors have an independent length.
   --  @field Stack_Frame_Index Zero-based current frame index within a stack sequence.
   --  @field CFAR Upstream binary32 average per-pixel false alarm rate, FA/pixel; retained as Float without widening or algorithm inference.
   --  @field Validity_Flag_Bitfield Opaque unsigned 16-bit validity for stack index/CFAR; bit definitions are not invented.
   --  @field TOV_UTC_NS Signed UTC-named time-of-validity nanosecond count; no more specific epoch is established.

   --  Complete CandidateObject. No floating-point value is clamped or
   --  normalized.
   type Candidate_Object is record
      System_Time_NS               : Long_Long_Integer;
      Detection_Category           : Interfaces.Unsigned_32;
      Sensor_Index                 : Interfaces.Unsigned_32;
      Subpixel                     : Row_Column;
      Intensity                    : Long_Float;
      Sensor_Relative_Unit         : Directional;
      Signal_To_Interference_Ratio : Long_Float;
      Signal_To_Noise_Ratio        : Long_Float;
   end record;

--  One-based row/column index into the exact three-by-three background patch,
   --  not a provider image coordinate.
   type Candidate_Background is array (Background_Index, Background_Index) of Interfaces.Integer_16;

--  Owned 3x3 signed 16-bit intensity patch around a candidate. Native row-major
   --  nine-sample storage is mapped explicitly to Ada row/column indices; signed
   --  values survive without unsigned conversion or intensity rescaling.

   --  Complete CandidateObjectPreProc. Every published getter is represented
   --  exactly once. No floating-point value is clamped or normalized:
   --  Candidate_Object_Quality is documented upstream as "0 to 1" but the
   --  published setter enforces nothing, and the sensor-relative unit vector
   --  is not renormalized. Detection_Category is an upstream bitfield and is
   --  deliberately not decoded. Each entry carries its OWN nested inertial
   --  state, distinct from the message-level one.
   type Candidate_Object_PreProc is record
      System_Time_NS                   : Long_Long_Integer;
      Detection_Category               : Interfaces.Unsigned_32;
      Sensor_Index                     : Interfaces.Unsigned_32;
      Subpixel                         : Row_Column;
      Intensity                        : Long_Float;
      Sensor_Relative_Unit             : Directional;
      Signal_To_Interference_Ratio     : Long_Float;
      Signal_To_Noise_Ratio            : Long_Float;
      Candidate_Object_With_Background : Candidate_Background;
      Clutter                          : Long_Float;
      Candidate_Object_Quality         : Long_Float;
      Sir_Delta                        : Long_Float;
      Inertial_State                   : Sensor_Inertial_State;
      Edge                             : Boolean;
      Az_Sigma                         : Long_Float;
      El_Sigma                         : Long_Float;
      Background_Normalizer            : Long_Float;
   end record;

--  Supported inbound callback alternatives, not outgoing send categories.
   --  @enum IRST_Track_Report_Event Conditionally required Track report callback.
   --  @enum Request_System_Track_Data_Event Optional inbound request for system data; no automatic response.
   --  @enum Candidate_Object_Message_Event Advertised candidate-message callback, required when its detection condition applies.
   --  @enum Candidate_Object_PreProc_Message_Event Optional inbound PreProc vector message.
   type Metadata_Event (Kind : Metadata_Kind := IRST_Track_Report_Event) is record
      case Kind is
         when IRST_Track_Report_Event =>
            Report : IRST_Track_Report;

         when Request_System_Track_Data_Event =>
            Request : Request_System_Track_Data;

         when Candidate_Object_Message_Event =>
            Candidates : Candidate_Object_Message;

         when Candidate_Object_PreProc_Message_Event =>
            Candidate_PreProcs : Candidate_Object_PreProc_Message;
      end case;
   end record;

AMS.MEL.IR.Track.System_Data.signature:
--  Owned upstream AzEl pair in radians, without clamping or normalization.
   --  @field Azimuth_Rad Azimuth component in radians.
   --  @field Elevation_Rad Elevation component in radians.

   --  Complete SystemTrackDataResponse. Every upstream field is represented
   --  exactly once. The system time stays signed nanoseconds, the ranges and
   --  rates stay in upstream meters and meters/second, and no value is clamped
   --  or normalized, because the upstream setters perform no such validation.
   type System_Track_Data_Response is record
      System_Time_NS : Long_Long_Integer;

      Command_ID : Interfaces.Unsigned_32;
      Request_ID : Interfaces.Unsigned_32;
      Track_ID   : Interfaces.Unsigned_32;

      Range_M              : Long_Float;
      Range_Rate_MPS       : Long_Float;
      Range_Error_M        : Long_Float;
      Range_Rate_Error_MPS : Long_Float;

      Az_El_Valid : Boolean;

      Inertial_Az_El : Azimuth_Elevation;
      Az_El_Error    : Azimuth_Elevation;

      Range_Valid : Boolean;
   end record;

--  Ada-owned CommandStatus. Reason_Description is copied into Ada-owned
   --  storage during Wait, so no C pointer escapes that call.
   type Command_Status is private;

--  Read the rejection category under the declared Rejected precondition;
   --  the body does not independently check the outcome.
   --  @param Result Explicitly rejected response result.
   --  @return Mapped upstream error code, not bridge admission exhaustion.
   function Description (Result : Response_Result) return String
   with Pre => Status (Result) = Rejected;

AMS.MEL.IR.Track.Updates.signature:
--  Owned Track-update-facing ECEF value. Deliberately independent of
   --  AMS.MEL.IR.Image so this package adds no Image dependency.
   type Directional is record
      X : Long_Float;
      Y : Long_Float;
      Z : Long_Float;
   end record;

--  Owned ECEF xyz components used separately for position and velocity.
   --  Pinned TrackDataUpdate specifies ECEF but not stronger component units;
   --  the bridge does not convert coordinates or infer a unit convention.
   --  @field X ECEF x component, copied through native double representation.
   --  @field Y ECEF y component, copied through native double representation.
   --  @field Z ECEF z component, copied through native double representation.

   --  Every published TrackDataUpdate covariance term, exactly 21 values,
   --  corresponding one-to-one with the C covariance record.
   type Track_Covariance is record
      XX   : Long_Float;
      XY   : Long_Float;
      XZ   : Long_Float;
      X_VX : Long_Float;
      X_VY : Long_Float;
      X_VZ : Long_Float;

      YY   : Long_Float;
      YZ   : Long_Float;
      Y_VX : Long_Float;
      Y_VY : Long_Float;
      Y_VZ : Long_Float;

      ZZ   : Long_Float;
      Z_VX : Long_Float;
      Z_VY : Long_Float;
      Z_VZ : Long_Float;

      VX_VX : Long_Float;
      VX_VY : Long_Float;
      VX_VZ : Long_Float;

      VY_VY : Long_Float;
      VY_VZ : Long_Float;

      VZ_VZ : Long_Float;
   end record;

--  All 21 individually named upstream Track covariance scalars. No implicit
   --  packed-matrix convention, units, symmetry expansion or transformation is
   --  invented. This differs from Image navigation's eighteen covariance terms.
   --  @field XX Upstream trackCovarianceXX scalar for the X/X pair.
   --  @field XY Upstream trackCovarianceXY scalar for the X/Y pair.
   --  @field XZ Upstream trackCovarianceXZ scalar for the X/Z pair.
   --  @field X_VX Upstream trackCovarianceXVx scalar for the X/velocity-X pair.
   --  @field X_VY Upstream trackCovarianceXVy scalar for the X/velocity-Y pair.
   --  @field X_VZ Upstream trackCovarianceXVz scalar for the X/velocity-Z pair.
   --  @field YY Upstream trackCovarianceYY scalar for the Y/Y pair.
   --  @field YZ Upstream trackCovarianceYZ scalar for the Y/Z pair.
   --  @field Y_VX Upstream trackCovarianceYVx scalar for the Y/velocity-X pair.
   --  @field Y_VY Upstream trackCovarianceYVy scalar for the Y/velocity-Y pair.
   --  @field Y_VZ Upstream trackCovarianceYVz scalar for the Y/velocity-Z pair.
   --  @field ZZ Upstream trackCovarianceZZ scalar for the Z/Z pair.
   --  @field Z_VX Upstream trackCovarianceZVx scalar for the Z/velocity-X pair.
   --  @field Z_VY Upstream trackCovarianceZVy scalar for the Z/velocity-Y pair.
   --  @field Z_VZ Upstream trackCovarianceZVz scalar for the Z/velocity-Z pair.
   --  @field VX_VX Upstream trackCovarianceVxVx scalar for the velocity-X/velocity-X pair.
   --  @field VX_VY Upstream trackCovarianceVxVy scalar for the velocity-X/velocity-Y pair.
   --  @field VX_VZ Upstream trackCovarianceVxVz scalar for the velocity-X/velocity-Z pair.
   --  @field VY_VY Upstream trackCovarianceVyVy scalar for the velocity-Y/velocity-Y pair.
   --  @field VY_VZ Upstream trackCovarianceVyVz scalar for the velocity-Y/velocity-Z pair.
   --  @field VZ_VZ Upstream trackCovarianceVzVz scalar for the velocity-Z/velocity-Z pair.

   --  Complete TrackDataUpdate. Every upstream field is represented exactly
   --  once. The two times stay in upstream epoch seconds and no value is
   --  clamped or normalized, because the upstream setters perform no such
   --  validation.
   type Track_Data_Update is record
      Platform_ID : Interfaces.Unsigned_32;

      Capability_UUID : UCI_ID;
      Activity_UUID   : UCI_ID;

      Track_ID : Interfaces.Unsigned_32;

      Entity_UUID : UCI_ID;

      Status : Track_Status;

      Time_Of_Validity_Seconds    : Long_Float;
      Time_Of_Last_Update_Seconds : Long_Float;

      Position_ECEF : Directional;
      Velocity_ECEF : Directional;

      Covariance : Track_Covariance;

      Maneuver_Probability : Long_Float;
      Track_Quality        : Long_Float;
   end record;

--  Ada-owned CommandStatus. Reason_Description is copied into Ada-owned
   --  storage during Wait, so no C pointer escapes that call.
   type Command_Status is private;

--  Owned terminal CommandStatus or explicit rejection. A successful outcome
   --  does not prove operational incorporation of kinematics by the provider.
   function Status (Result : Update_Result) return Update_Outcome;

AMS.MEL.IR.Track.signature:
--  Explicitly enable an Attached channel; already Enabled is idempotent.
   --  Provider refusal/exception raises a provider error and marks failure;
   --  retrying Enable does not recover a failed lifecycle.
   --  @param Channel Open Attached or already Enabled owner; serialize owner operations.
   function Capabilities (Channel : Track_Channel) return IR.Channel.Channel_Capability;

--  Owned Track-facing NED value. Deliberately independent of
   --  AMS.MEL.IR.Image so this package adds no Image dependency.
   type North_East_Down is record
      North : Long_Float;
      East  : Long_Float;
      Down  : Long_Float;
   end record;

--  Copied north/east/down components independent of Image package types.
   --  Pinned directional/report declarations establish no component units or
   --  normalization; do not treat this as an automatically transformed position.
   --  @field North Reported north component without bridge conversion.
   --  @field East Reported east component without bridge conversion.
   --  @field Down Reported down component without bridge conversion.

   --  Complete IRSTTrackReport. Every upstream getter is represented exactly
   --  once and no floating-point value is clamped or normalized.
   type IRST_Track_Report is record
      System_Time_NS : Long_Long_Integer;
      Activity_ID    : Interfaces.Unsigned_32;

      Measured_NED       : North_East_Down;
      Measured_Intensity : Long_Float;
      Measured_SNR       : Long_Float;

      Filtered_NED       : North_East_Down;
      Filtered_Intensity : Long_Float;
      Filtered_SNR       : Long_Float;

      Range_M            : Long_Float;
      Range_Error_M      : Long_Float;
      Spatial_Extent_Rad : Long_Float;
      Track_Quality      : Long_Float;
      Clutter            : Long_Float;

      Age_NS : Long_Long_Integer;

      State : IRST_Track_State;
      Mode  : IRST_Track_Mode;
   end record;

AMS.MEL.IR.signature:
--  IR foundation values and the legacy copied-frame image stream. This
   --  stream supports host-memory, single-band, eight-bit monochrome images;
   --  it performs no decoding, flipping, resampling or coordinate transforms.
   --  The richer image child package has separate full-header and frame-lease
   --  APIs; their capabilities must not be inferred for this legacy Frame.

   subtype Byte is Interfaces.Unsigned_8;

--  Exactly sixteen identifier bytes indexed zero through fifteen. These are
   --  binary identity bytes, not a UTF-8 label or a textual UUID encoding.

   type Pixel_Array is array (Natural range <>) of Byte;

--  Host-system forward/right/down offsets in meters and an external key for
   --  the logical mounting location. No coordinate transformation is performed.

   function Create_Component_Location
     (Offset_X_M  : Long_Float;
      Offset_Y_M  : Long_Float;
      Offset_Z_M  : Long_Float;
      Key         : String;
      System_Name : String) return Component_Location;

--  Ada-owned image-channel configuration copied into native storage on open.
   --  Buffer sizes/count and receive-queue capacity are bridge resource choices,
   --  not image transformations or promises of provider throughput.

   function Create_Image_Config
     (Channel_ID      : UCI_ID;
      Platform_ID     : UCI_ID;
      Sensor_Location : Component_Location;
      Buffer_Count    : Positive := 3;
      Buffer_Size     : Positive := 1_048_576;
      Queue_Capacity  : Positive := 4) return Image_Config;

--  Reported image flip configuration; the bridge does not flip the pixels.
   --  @enum No_Flip No flip is indicated.
   --  @enum Vertical A vertical flip is indicated.
   --  @enum Horizontal A horizontal flip is indicated.
   --  @enum Both Both vertical and horizontal flips are indicated.
   type Frame (Pixel_Count : Natural) is record
      System_Time_NS      : Long_Long_Integer;
      Integration_Time_NS : Long_Long_Integer;
      Width               : Interfaces.Unsigned_32;
      Height              : Interfaces.Unsigned_32;
      Bits_Per_Pixel      : Interfaces.Unsigned_32;
      Number_Of_Bands     : Interfaces.Unsigned_32;
      Horizontal_FOV_Rad  : Long_Float;
      Vertical_FOV_Rad    : Long_Float;
      Frame_ID            : Interfaces.Unsigned_32;
      Subframe_ID         : Interfaces.Unsigned_32;
      Subframe_Total      : Interfaces.Unsigned_32;
      Kind                : Image_Type;
      Flip                : Image_Flip;
      Image_Flags         : Interfaces.Unsigned_32;
      Dither_Row          : Long_Float;
      Dither_Column       : Long_Float;
      Row_Offset          : Interfaces.Unsigned_32;
      Column_Offset       : Interfaces.Unsigned_32;
      Band_Index          : Byte;
      Pixels              : Pixel_Array (1 .. Pixel_Count);
   end record;

--  Unsigned 64-bit native stream diagnostic count.

   type Stream_Counters is record
      Frames_Received           : Counter;
      Frames_Dropped_Queue_Full : Counter;
      Malformed_Or_Unsupported  : Counter;
   end record;

AMS.MEL.RF.C2.Data_Pipes.signature:
--  Copied outer group lookup key and nested pipes, including successful empty groups. No
   --  native/provider ownership remains.

   type Data_Pipe_Connection is private;

--  Copied inner lookup key, distinct provider-returned label and associated endpoint set.
   --  Inner pipes preserve provider std::map traversal, including aliases.

   type Endpoint_ID_Array is array (Natural range <>) of Interfaces.Unsigned_64;

--  Caller-owned unsigned 64-bit IDs for a provider set request. All bits survive; input
   --  order is insignificant and duplicates collapse. A null array is a valid empty set.

   function Snapshot (Object : Virtual_Aperture'Class) return Connection_Snapshot;

AMS.MEL.RF.C2.Element_Groups.signature:
--  Copied lookup key, provider display label, direction and numeric limits, with explicit
   --  nested-pipe inclusion state. No provider ownership remains.

   type Data_Pipe_Info is private;

AMS.MEL.RF.C2.Interval_Status.signature:
--  Limited observer with explicit Close and non-raising controlled cleanup.
   --  Neither cleanup path calls provider unregister or waits for quiescence.
   function Open
     (Object                                       : Job;
      Queue_Capacity                               : Positive;
      Max_Event_Log_Entries, Max_Activity_ID_Bytes : Natural) return Stream;

--  Ada-owned status, log and arbitrary binary activity bytes. Copies survive
   --  Stream and Job closure and retain no native/provider owner.
   type Event_Log_Entry is private;

AMS.MEL.RF.C2.Local_Functions.signature:
--  Ada-owned catalog copy sorted by provider numeric LF type-ID map keys. Zero-instance
   --  entries remain present; copies survive provider/VA/C2 closure without a native owner.

   type Local_Function_Info is private;

--  Copied LF type-ID and instance count per VA instance, not evidence of membership
   --  validation or physical LF execution.

   type Status_List is private;

--  Read the catalog count of instances of this LF type within each VA instance.
   --  @param Value Ada-owned copied value; no provider access or retained provider owner.
   --  @return Unsigned 64-bit copy of the native size t count without narrowing.

   function Snapshot_Local_Function_Status
     (Object                 : Virtual_Aperture'Class;
      VA_Instance_ID         : Interfaces.Unsigned_32;
      Local_Function_Type_ID : Interfaces.Unsigned_32) return Status_List;

AMS.MEL.RF.C2.Transmit_Power.signature:
--  Unsigned provider transmit element-group ID, not a label. Native size t representability
   --  is checked before provider entry; failure raises Provider Error without truncation.

   subtype Weight_Type_ID is Interfaces.Unsigned_64;

--  Unsigned provider weight-type ID, not an owned Weights object. Must fit native size t;
   --  unrepresentable values raise Provider Error before provider entry.

   type UV_Line_Of_Sight is record
      U : Long_Float;
      V : Long_Float;
   end record;

--  Upstream AnglePair line-of-sight/stabilization components, forwarded without
   --  normalization, conversion or local physical range checks.
   --  @field U First upstream U component, passed unchanged.
   --  @field V Second upstream V component, passed unchanged.

   function Radiated_Power_DBW
     (Object              : Virtual_Aperture'Class;
      Element_Group       : Element_Group_ID;
      Power_Mode_ID       : Interfaces.Unsigned_32;
      Attenuation_DB      : Long_Float;
      Weight_Type         : Weight_Type_ID;
      Center_Frequency_Hz : Long_Float;
      Line_Of_Sight       : UV_Line_Of_Sight;
      VA_Instance_ID      : Interfaces.Unsigned_32 := 0) return Long_Float;

AMS.MEL.RF.C2.Virtual_Aperture_Notificat.signature:
--  Consume one pending signal. Multiple callback entries coalesce into one
   --  pending notification; successful waits increment delivered, not entries.
   --  Stop clears pending and has priority. Raises Timeout Error on absence,
   --  Subscription Stopped on stop, and Provider Error for other native errors.
   --  @param Object Open local subscription; no provider getter is called.
   --  @param Timeout_Milliseconds Maximum wait in milliseconds; zero polls.
   type Subscription_Statistics is record
      Callback_Entries        : Interfaces.Unsigned_64;
      Callbacks_Coalesced     : Interfaces.Unsigned_64;
      Notifications_Delivered : Interfaces.Unsigned_64;
      Callbacks_After_Stop    : Interfaces.Unsigned_64;
      Pending, Stopped        : Boolean;
   end record;

AMS.MEL.RF.C2.signature:
--  A bounded request or Job-status wait expired. Zero milliseconds polls.
   --  Timeout neither cancels work nor consumes a request, result or owner.
   type Virtual_Aperture_Config is private;

--  Ada-owned request values: definition ID, priority, file information,
   --  ordered local-function strings and Common MEL capability IDs. Construction
   --  allocates no provider aperture and implies no physical activation.
   function Create_Virtual_Aperture_Config
     (VA_Definition_ID        : Interfaces.Unsigned_32;
      Priority                : Interfaces.Unsigned_32;
      VA_Definition_File_Info : String) return Virtual_Aperture_Config;

--  Copied immutable terminal outcome, error code and diagnostic. Contains no
   --  resource owner; closing the request does not invalidate this value.
   function Outcome (Result : Virtual_Aperture_Result) return Request_Outcome;

--  TX JobRequest requirements only; this does not execute a TX interval.
   --  Power is exact provider-defined TxPowerLevel, not a TxPowerModeID.
   type TX_Element_Group_Config is private;

--  Ada-owned TX Job requirements: label, duty, power level and frequency
   --  ranges. This value constructs no event and activates no transmitter.
   function Create_TX_Element_Group
     (Label               : String;
      TX_Power_Level      : Interfaces.Unsigned_32;
      Desired_Duty_Factor : Long_Float := 1.0) return TX_Element_Group_Config;

--  Append a copied TX frequency range in caller order. Nonfinite or reversed
   --  bounds raise a constraint error; no bridge positivity restriction applies.
   --  @param Group TX requirements to extend, not a running interval.
   --  @param Min_Hz Finite lower center-frequency bound in hertz.
   --  @param Max_Hz Finite upper center-frequency bound in hertz, at least the lower bound.
   function Create_RX_Element_Group
     (Label               : String;
      Desired_Duty_Factor : Long_Float := 1.0;
      Data_Pipe_Label     : String := "default") return RX_Element_Group_Config;

--  Append a copied endpoint identity to the configured default pipe.
   --  Pipe collections retain insertion order. Duplicate IDs within one
   --  collection raise a constraint error; empty collections are omitted.
   --  @param Group RX requirements; use the default pipe label saved at construction.
   --  @param ID Exact unsigned 64-bit endpoint ID to associate at submission.
   procedure Append_Endpoint_ID
     (Group           : in out RX_Element_Group_Config;
      Data_Pipe_Label : String;
      ID              : Interfaces.Unsigned_64);

--  Owned caller-selected pointing value, not a coordinate transformation or
   --  capability query. Constructors preserve active coordinates and IEEE value
   --  classification, including signed zero, infinity and NaN; there is no NaN
   --  payload-bit promise. No clamping, wrapping, geodesy or finite/range check is
   --  performed on coordinates. Only ECEF/LLA UTC fractions are constrained.
   function Create_ECEF_Pointing
     (Location_X_M, Location_Y_M, Location_Z_M       : Long_Float;
      Velocity_X_MPS, Velocity_Y_MPS, Velocity_Z_MPS : Long_Float;
      Time_Of_Validity                               : UTC_Time) return Pointing;

--  Read the active variant without inspecting inactive coordinates.
   --  @param Value Owned pointing value.
   --  @return Active alternative; no provider support claim is implied.
   type ECEF_Coordinates is record
      X, Y, Z : Long_Float;
   end record;

--  Arbitrary identity bytes for Job configuration: length, order, embedded
   --  zeros and high bits are data. Empty values are allowed; not UTF-8 or a UUID.
   type Unsigned_32_Array is array (Natural range <>) of Interfaces.Unsigned_32;

--  Unsigned ID sequence, including empty input. Power-mode submission converts
   --  it to a set, so duplicates collapse and caller order is not promised there.
   type Job_Config is private;

--  Mark estimated pointing absent; submission then omits its setter rather
   --  than reading or initializing the pinned default ECEF numeric storage.
   --  @param Config Owned Job requirements whose optional point is cleared.
   function Create_Job_Config
     (Request_ID, Priority       : Interfaces.Unsigned_32;
      Group                      : RX_Element_Group_Config;
      Precedence_Within_Priority : Interfaces.Unsigned_32 := 0;
      Interruptable              : Boolean := False) return Job_Config;

--  Append an exact instance selection; retain order, duplicates and all bits.
   --  No provider membership check occurs in this local operation.
   --  @param Config Owned Job requirements to extend.
   --  @param ID Unsigned 32-bit VA instance selection value.
   function Create_Job_Config
     (Request_ID, Priority       : Interfaces.Unsigned_32;
      Group                      : TX_Element_Group_Config;
      Precedence_Within_Priority : Interfaces.Unsigned_32 := 0;
      Interruptable              : Boolean := False) return Job_Config;

--  Copied immutable terminal request data, not a Job owner or execution status.
   --  Result values remain independent of request closure and Claim.
   function Outcome (Result : Job_Result) return Request_Outcome;

--  Independent copyable settings and ordered threshold pairs owned by Ada.
   --  Default initialization is DBQ, leading/trailing M/N 0/0, minimum width
   --  zero femtoseconds, 50-percent time tag and no thresholds. Set on RX only;
   --  no detection algorithm, capability or pulse performance is established.

   function Create_Pulse_Detection_Settings
     (Reference                                    : Pulse_Threshold_Reference;
      Leading_M, Leading_N, Trailing_M, Trailing_N : Interfaces.Unsigned_8;
      Min_Pulse_Width_Femtoseconds                 : Interfaces.Integer_64;
      Time_Tag_Threshold                           : Pulse_Time_Tag_Threshold)
      return Pulse_Detection_Settings;

--  Scalar descriptor only: numeric address, not a pointer. No endpoint or
   --  backing memory is acquired, checked, owned or transferred by this API.
   function Waveform_Stream
     (Endpoint_ID, Start_Address, Num_Bytes : Interfaces.Unsigned_64;
      Sample_Format                         : Stream_Sample_Format := Stream_Complex_Cartesian;
      Item_Format                           : Stream_Item_Format := Stream_Fixed_Point_Signed;
      Repeat_Mode                           : Stream_Repeat_Mode := Stream_Repeat_From_Top)
      return Modulation_Config;

--  Select kind 7, the outer native WaveformStream alternative, and copy six scalar descriptors. No endpoint acquisition, allocation, registration, mapping, dereference or transfer of backing memory occurs. Application/provider own memory extent, lifetime and capability obligations; zero values are structurally valid, not proof of an executable stream.
   --  @param Endpoint_ID Full unsigned 64-bit endpoint identity; no existence query.
   --  @param Start_Address Full unsigned 64-bit numeric descriptor, not an Ada access value or bridge-owned pointer.
   --  @param Num_Bytes Unsigned 64-bit bytes per iteration; must fit native size t at Add (checked Ada conversion/round trip). Zero is accepted.
   --  @param Sample_Format Sample shape, default ComplexCartesian in the constructor.
   --  @param Item_Format Numeric item descriptor, default FixedPointSigned in the constructor.
   --  @param Repeat_Mode Provider repeat policy, default RepeatFromTop in the constructor.
   --  @return Owned stream descriptor without any backing-storage owner.

   procedure Replace_Waveform_Stream
     (Config                                : in out Modulation_Config;
      Endpoint_ID, Start_Address, Num_Bytes : Interfaces.Unsigned_64;
      Sample_Format                         : Stream_Sample_Format;
      Item_Format                           : Stream_Item_Format;
      Repeat_Mode                           : Stream_Repeat_Mode);

--  One Cartesian complex pair with signed 8-bit components; no scaling or clipping.
   --  @field Real Real (I) component, full signed 8-bit integer domain.
   --  @field Imag Imaginary (Q) component, full signed 8-bit integer domain.

   type Waveform_Sample_I16 is record
      Real, Imag : Interfaces.Integer_16;
   end record;

--  Ordered signed 8-bit Cartesian pairs with Positive indices and arbitrary lower bound.
   --  Null arrays are accepted; counts mean complex pairs, not bytes or individual components.

   type Waveform_Sample_I16_Array is array (Positive range <>) of Waveform_Sample_I16;

--  Nonnegative signed 32-bit profile index, 0 through Integer 32 Last.
   --  Must fit native int and refer to a profile in the same CustomWaveform at Add;
   --  there is no -1 sentinel for an inner waveform step.

   type Waveform_Profile is private;

--  Owned ordered profile-index/iteration steps, initially empty; copies are independent.
   --  No chip duration is stored in a step: duration belongs to the selected profile.

   type Waveform_Pattern_List is private;

--  Replace the numeric value and its independent update flag; False does not erase Value. No wrapping, normalization, clamping or finite validation; copied native double retains signed zero and nonfinite classification.
   --  @param Profile Owned waveform profile.
   --  @param Value Amplitude-reduction factor, pinned intended range 0 through 1, not enforced by the bridge.
   --  @param Update Provider request to apply this field when the profile is applied, not bridge execution.

   procedure Append_Profile
     (Table   : in out Waveform_Profile_Table;
      Profile : Waveform_Profile;
      Index   : out Waveform_Profile_Index);

--  Append an independent copied profile in order without merging identical values. Conversion of a full table length beyond the index domain raises Constraint Error before append.
   --  @param Table Owned profile table.
   --  @param Profile Complete value and update flags to copy.
   --  @param Index Returned zero-based position; not an Ada Positive index.

   procedure Append_Step
     (Pattern             : in out Event_Waveform_Pattern;
      Profile_Index       : Waveform_Profile_Index;
      Num_Chip_Iterations : Interfaces.Integer_32 := 1);

--  Select bridge kind 0 and the empty native Tone alternative; no payload or synthesis.
   --  @return Owned Tone configuration, distinct from the -1 reference sentinel.

   type Modulation_Boolean_Array is array (Positive range <>) of Boolean;

--  Ordered logical values in ascending Positive index order, including null arrays.
   --  Each Boolean is serialized separately as 0/1, then copied to native vector<bool>; not packed wire bits.

   function On_Off_Keying (Pulse_Enabled : Modulation_Boolean_Array) return Modulation_Config;

--  Select kind 3 and copy ordered enables. At Add the list length must equal the interval sequence repeat count, even for an unused definition. One OOK entry cannot be referenced by two distinct TX events in that interval; repeated references from one event are allowed. No execution is performed.
   --  @param Pulse_Enabled Ordered pulse enables, including empty only with repeat count zero at Add.
   --  @return Owned OOK configuration.

   function CPFSK_Pulse
     (Chip_Data                                               : Modulation_Boolean_Array;
      Pulse_Duration_Femtoseconds, Chip_Duration_Femtoseconds : Interfaces.Integer_64;
      Frequency_Offset_Hz                                     : Long_Float)
      return Modulation_Config;

--  Clear the stored list and mark it absent, retaining native default {-1} during subsequent event construction; distinct from explicit empty.
   --  @param Event Owned TX configuration.

   procedure Set_Empty_Modulation_References (Event : in out TX_Transmit_Event_Config);

--  Clear the stored list and mark it present-empty, so native setModIndex receives an empty vector rather than default {-1}.
   --  @param Event Owned TX configuration.

   function Create_TX_Transmit_Event
     (Event_ID                                  : Interfaces.Unsigned_32;
      Element_Group_Label                       : String;
      Start_Femtoseconds, Duration_Femtoseconds : Interfaces.Integer_64;
      Center_Frequency_Hz                       : Long_Float;
      TX_Attenuation_DB                         : Long_Float := 0.0;
      Rise_Duration_Femtoseconds                : Interfaces.Integer_64 := 0;
      Fall_Duration_Femtoseconds                : Interfaces.Integer_64 := 0)
      return TX_Transmit_Event_Config;

--  Replace the TX attenuation value without clamping, quantization or capability queries. This is attenuation, not TX Power Level or TX Power Mode ID; native double preserves IEEE classification and signed zero, not NaN payload bits.
   --  @param Event Owned TX configuration.
   --  @param Value Attenuation in dB; nonfinite values are not rejected by the bridge.

   procedure Set_TX_Edge_Durations
     (Event                                : in out TX_Transmit_Event_Config;
      Rise_Femtoseconds, Fall_Femtoseconds : Interfaces.Integer_64);

--  Mark RX pulse settings absent; retained inactive Ada values are not submitted. Native construction leaves upstream default pulse settings rather than clearing a running detector.
   --  @param Event Owned RX configuration.

   type Execution_Type is (Normal, Conditional);

--  Append a copied RX group index, retaining order and duplicates. Empty is allowed. Add checks size t representability, not the Job group count or connectivity; these are provider indices, not labels or Ada positions.
   --  @param Event Owned RX configuration to extend.
